// 在已初始化Vue/i18n/Pinia的组件harness中导入，不在冷模块阶段调用翻译。
import { BASE_VIEW_CONFIG } from '@/views/chart/components/editor/util/chart'
import { cloneDeep, set } from 'lodash-es'
export function materialize(doc, fixtureId) {
  const f = doc.fixtures[fixtureId]
  const view = cloneDeep(BASE_VIEW_CONFIG)
  for (const [path, value] of Object.entries(f.view_assignments)) set(view, path, cloneDeep(value))
  const element = cloneDeep(f.element)
  const request = cloneDeep(view)
  request.customFilter = cloneDeep(doc.source_tree_persisted.value)
  for (const [path, value] of Object.entries(f.wire_request_assignments || {})) set(request, path, cloneDeep(value))
  const wireResponse = cloneDeep(request)
  wireResponse.data = cloneDeep(f.response_data)
  for (const [path, value] of Object.entries(f.response_assignments)) set(wireResponse, path, cloneDeep(value))
  for (const [path, value] of Object.entries(f.wire_response_assignments || {})) set(wireResponse, path, cloneDeep(value))
  const response = cloneDeep(wireResponse)
  for (const [path, value] of Object.entries(f.prepared_response_assignments || {})) set(response, path, cloneDeep(value))
  const prepared = f.expected.needsQuery === false ? {kind:'static-picture',local:cloneDeep(request)} : {kind:'queried',request,response}
  return {view, element, request, wireResponse, prepared, geo: f.geo_ref ? cloneDeep(doc.geojson[f.geo_ref.split('/').at(-1)]) : undefined}
}
